function(form) {
  if (form.get('Does the patient need medication?').getValue() === 'Yes') {
    form.get('If yes, which medicines? (applied only for Silicosis)').setHidden(false);
  } else {
    form.get('If yes, which medicines? (applied only for Silicosis)').setHidden(true);
  }

}

function(form) {
  var multi_select = form.get('Which of these identification cards does the patient have?').currentRecord.value.value;
  var length = multi_select == undefined ? 0 : multi_select.length;
  var arr = []
  if (length == 0) {
    form.get("Other Notes").setHidden(true);
  } else {
    for (var i = 0; i < length; i++) {
      var name = multi_select[i].displayString == undefined ? multi_select[i].name : multi_select[i].displayString;
      arr.push(name);
      if (arr.includes('Other Notes'))
        form.get("Other Notes").setHidden(false);
      else
        form.get("Other Notes").setHidden(true);
    }
  }
}

